$notice=is_string($notice??null)?$notice:'';
$csrf=is_string($csrf??null)?$csrf:'';
$brandName=is_string($brandName??null)?$brandName:'Talyvane';
$formValues=is_array($formValues??null)?$formValues:[];
$ambiguousTime=is_array($ambiguousTime??null)?$ambiguousTime:null;
$money=static fn(mixed $minor,mixed $precision):string=>number_format(((int)$minor)/(10**max(0,min(4,(int)$precision))),max(0,min(4,(int)$precision)),'.',',');
$localTime=static function(array $item,string $key):string {
    try { return (new DateTimeImmutable((string)$item[$key],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone((string)$item['time_zone']))->format('D, d M Y · H:i'); }
    catch(Throwable) { return (string)($item[$key]??''); }
};
